css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .5); position: relative; }
.loader::before, .loader::after { content: ''; position: absolute; top: 50%; width: calc(var(--loader-size) * .5); height: calc(var(--loader-size) * .5); margin-top: calc(var(--loader-size) * -.25); border: calc(var(--loader-size) * .045) solid color-mix(in srgb, var(--accent-2) 35%, transparent); border-radius: 50%; box-sizing: border-box; }
.loader::before { left: 0; }
.loader::after { right: 0; }
.loader span { position: absolute; top: 50%; left: 50%; width: calc(var(--loader-size) * .14); height: calc(var(--loader-size) * .14); margin: calc(var(--loader-size) * -.07) 0 0 calc(var(--loader-size) * -.07); border-radius: 50%; background: var(--accent); box-shadow: 0 0 calc(var(--loader-size) * .12) var(--accent); animation: infinity calc(var(--loader-speed) * 2.2) linear infinite; }
@keyframes infinity { 0% { transform: translate(calc(var(--loader-size) * .25), 0); } 12.5% { transform: translate(calc(var(--loader-size) * .177), calc(var(--loader-size) * -.125)); } 25% { transform: translate(0, 0); } 37.5% { transform: translate(calc(var(--loader-size) * -.177), calc(var(--loader-size) * .125)); } 50% { transform: translate(calc(var(--loader-size) * -.25), 0); } 62.5% { transform: translate(calc(var(--loader-size) * -.177), calc(var(--loader-size) * -.125)); } 75% { transform: translate(0, 0); } 87.5% { transform: translate(calc(var(--loader-size) * .177), calc(var(--loader-size) * .125)); } 100% { transform: translate(calc(var(--loader-size) * .25), 0); } }
